    // Create array of output messages (one per data point)
    const messages = result.data.map(point => ({
        payload: {
            x: point.timestamp,
            y: point.value
        },
        topic: REGISTER_TO_EXTRACT,
        register: result.name,
        unit: point.unit,
        time: point.time
    }));

    // Return array of messages - Node-RED will send each separately
