// Verify + Decrypt ESP32 "SecureLink" payloads
// Topic shape: devices/<deviceId>/data
// settings.js must have: functionGlobalContext: { crypto: require('crypto') }

const crypto = global.get('crypto');

// ---- PSK (32 bytes) you provisioned on the ESP32 ----
const PSK = Buffer.from(
  "4968A7E8835BC6EC5BDBE15AA9E7C478E5616E33AA0CC4CADB53A81AA20FA727",
  "hex"
);

// Header layout (matches SecureLink.h)
const HDR_LEN = 1 + 1 + 2 + 8 + 8 + 12; // 32
const MAC_LEN = 32;
const INFO = Buffer.from("EcoWatt");
const OFF_VER = 0, OFF_TYPE = 1, OFF_BOOT = 4, OFF_SEQ = 12, OFF_IV = 20;

function hkdf48(ikm, salt, info) {
  const prk = crypto.createHmac("sha256", salt).update(ikm).digest();
  let T = Buffer.alloc(0), okm = Buffer.alloc(0), ctr = 0;
  while (okm.length < 48) { ctr++; T = crypto.createHmac("sha256", prk).update(Buffer.concat([T, info, Buffer.from([ctr])])).digest(); okm = Buffer.concat([okm, T]); }
  return okm.slice(0, 48);
}
function deriveKeys(deviceId) {
  const salt = crypto.createHash("sha256").update(deviceId).digest();
  const okm = hkdf48(PSK, salt, INFO);
  return { K_enc: okm.slice(0, 16), K_mac: okm.slice(16, 48) };
}
function timingSafeEq(a, b) { if (a.length !== b.length) return false; return crypto.timingSafeEqual(a, b); }
function parseHeader(buf) {
  if (buf.length < HDR_LEN + MAC_LEN) throw Error(`short packet (${buf.length})`);
  const hdr = buf.slice(0, HDR_LEN);
  const ct = buf.slice(HDR_LEN, buf.length - MAC_LEN);
  const mac = buf.slice(buf.length - MAC_LEN);
  return {
    hdr, ct, mac,
    ver: hdr.readUInt8(OFF_VER),
    type: hdr.readUInt8(OFF_TYPE),
    boot: hdr.readBigUInt64LE(OFF_BOOT),
    seq: hdr.readBigUInt64LE(OFF_SEQ),
    iv12: hdr.slice(OFF_IV, OFF_IV + 12)
  };
}
function verifyHmac(K_mac, hdr, ct, mac) {
  const tag = crypto.createHmac("sha256", K_mac).update(hdr).update(ct).digest();
  if (!timingSafeEq(tag, mac)) throw Error("bad hmac");
}
function antiReplayOK(deviceId, boot, seq) {
  const key = `replay:${deviceId}`;
  const st = context.get(key) || { lastBoot: 0n, lastSeq: 0n };
  const ok = (boot > st.lastBoot) || (boot === st.lastBoot && seq > st.lastSeq);
  if (ok) context.set(key, { lastBoot: boot, lastSeq: seq });
