}
function hexHead(buf, n = 16) { return Array.from(buf.slice(0, n)).map(b => b.toString(16).padStart(2, "0")).join(""); }

try {
  // Expect: devices/<deviceId>/data
  const parts = (msg.topic || "").split("/");
  if (parts.length < 3 || parts[0] !== "devices" || parts[2] !== "data")
    throw Error(`unexpected topic: ${msg.topic}`);
  const deviceId = parts[1];

  // Base64 input (string or Buffer containing base64 text)
  let b64;
  if (Buffer.isBuffer(msg.payload)) b64 = msg.payload.toString("utf8").trim();
  else if (typeof msg.payload === "string") b64 = msg.payload.trim();
  else throw Error("payload must be base64 string or Buffer");
  const buf = Buffer.from(b64, "base64");

  node.status({ fill: "blue", shape: "dot", text: `rx ${buf.length}B head:${hexHead(buf)}` });

  // Guard: if first byte looks like '{' → you sent plaintext JSON by mistake
  if (buf.length && (buf[0] === 0x7B || buf[0] === 0x5B)) {
    node.warn("[SEC] plaintext JSON received; device likely not sealing this message.");
    try { msg.payload = JSON.parse(buf.toString("utf8")); } catch { msg.payload = buf.toString("utf8"); }
    msg.secure = { deviceId, note: "plaintext_received" };
