  const plain = decryptAesCtr(K_enc, iv12, ct);
  let obj;
  try { obj = JSON.parse(plain.toString("utf8")); }
  catch { throw Error("plaintext is not valid JSON"); }

  msg.payload = obj;
  msg.secure = { deviceId, type, boot: boot.toString(), seq: seq.toString() };
  return msg;

} catch (e) {
  node.status({ fill: "red", shape: "ring", text: e.message });
  node.warn(`[SEC] drop: ${e.message}`);
  return null;
}

// Downlink encryptor for ESP32 SecureLink
// Topic shape: devices/<deviceId>/write
// Input:  msg.payload = object or string (plaintext to send)
// Output: msg.payload = base64(sealed), msg.secure metadata preserved

const crypto = global.get('crypto');

// ---- PSK (32 bytes) must match the ESP32 ----
