const HDR_LEN = 1 + 1 + 2 + 8 + 8 + 12; // 32
const INFO    = Buffer.from("EcoWatt");
const OFF_VER = 0, OFF_TYPE = 1, OFF_BOOT = 4, OFF_SEQ = 12, OFF_IV = 20;

function hkdf48(ikm, salt, info){
  const prk = crypto.createHmac("sha256", salt).update(ikm).digest();
  let T = Buffer.alloc(0), okm = Buffer.alloc(0), ctr = 0;
  while (okm.length < 48) {
    ctr++;
    T = crypto.createHmac("sha256", prk).update(Buffer.concat([T, info, Buffer.from([ctr])])).digest();
    okm = Buffer.concat([okm, T]);
  }
  return okm.slice(0,48);
}
function deriveKeys(deviceId){
  const salt = crypto.createHash("sha256").update(deviceId).digest();
  const okm  = hkdf48(PSK, salt, INFO);
  return { K_enc: okm.slice(0,16), K_mac: okm.slice(16,48) };
}
function u64le(bn){
  const b = Buffer.alloc(8); b.writeBigUInt64LE(bn); return b;
}

try {
  // Expect: devices/<deviceId>/write
  const parts = (msg.topic || "").split("/");
  if (parts.length < 3 || parts[0] !== "devices" || parts[2] !== "write") {
    throw Error(`unexpected topic: ${msg.topic}`);
