  const deviceId = parts[1];

  // Serialize plaintext
  let plain;
  if (typeof msg.payload === "string") plain = Buffer.from(msg.payload, "utf8");
  else plain = Buffer.from(JSON.stringify(msg.payload ?? {}), "utf8");

  // Derive keys
  const { K_enc, K_mac } = deriveKeys(deviceId);

  // Per-device counters for downlink (anti-replay at device side)
  const ck = `down:${deviceId}`;
  let st = context.get(ck) || { boot: 0n, seq: 0n };
  if (st.boot === 0n) { st.boot = BigInt(Date.now()); st.seq = 0n; }
  st.seq += 1n; context.set(ck, st);

