  // Assemble & base64
  const sealed = Buffer.concat([hdr, ct, mac]);
  msg.payload = sealed.toString("base64");

  // keep topic as-is (devices/<id>/write) for your MQTT out
  msg.secure = { deviceId, type: (msg.secureType ?? 2), boot: st.boot.toString(), seq: st.seq.toString(), ct_len: ct.length };
  return msg;

} catch (e) {
  node.status({fill:"red",shape:"ring",text:e.message});
  node.warn(`[SEC] downlink error: ${e.message}`);
  return null;
}

