function toBase64(buf) { return Buffer.from(buf).toString('base64'); }
function fromBase64(s) { return Buffer.from(s, 'base64'); }
function hexToBuf(hex) { return Buffer.from(hex.replace(/[^0-9a-f]/gi, ''), 'hex'); }
function bufToHex(buf) { return Buffer.from(buf).toString('hex').toUpperCase(); }

/**
 * SecureLink seal compatible with your device:
 * Header (packed, little-endian where applicable):
 *  struct SecureHdr {
 *    uint8_t   ver;         // 1
 *    uint8_t   type;        // app message type (use 2 for FOTA cmd)
 *    uint16_t  reserved;    // 0
 *    uint64_t  boot_epoch;  // from device (store per device)
 *    uint64_t  seq;         // increment per message (store per device)
 *    uint8_t   iv[12];      // 12-byte random; device pads to 16 with 0x00000000
 *  };
 * Cipher = AES-256-CTR(key=PSK, iv16 = iv12||00000000)
 * Tag    = HMAC-SHA256(key=PSK) over (header||ciphertext)
 * Final  = base64(header||ciphertext||tag)
 */
function securelinkSeal(pskBuf, hdr, plaintextBuf) {
    const iv12 = crypto.randomBytes(12);
    const iv16 = Buffer.concat([iv12, Buffer.alloc(4, 0)]); // pad to 16 for Node's AES-CTR
    // pack header
    const h = Buffer.alloc(1 + 1 + 2 + 8 + 8 + 12);
    let o = 0;
    h.writeUInt8(hdr.ver || 1, o++);
    h.writeUInt8(hdr.type || 2, o++);
    h.writeUInt16LE(0, o); o += 2;
    h.writeBigUInt64LE(BigInt(hdr.boot_epoch || 0), o); o += 8;
    h.writeBigUInt64LE(BigInt(hdr.seq || 0), o); o += 8;
    iv12.copy(h, o); o += 12;

    const cipher = crypto.createCipheriv('aes-256-ctr', pskBuf, iv16);
    const ct = Buffer.concat([cipher.update(plaintextBuf), cipher.final()]);

    const mac = crypto.createHmac('sha256', pskBuf).update(h).update(ct).digest(); // 32 bytes

    return toBase64(Buffer.concat([h, ct, mac]));
}

/** SHA-256 hex of a Buffer */
function sha256Hex(buf) {
    return crypto.createHash('sha256').update(buf).digest('hex').toUpperCase();
}

// save helpers to flow context
flow.set('fota_helpers', { toBase64, fromBase64, hexToBuf, bufToHex, securelinkSeal, sha256Hex });

return msg;

