  const mac = buf.slice(buf.length - MAC_LEN);
  return {
    hdr, ct, mac,
    ver: hdr.readUInt8(OFF_VER),
    type: hdr.readUInt8(OFF_TYPE),
    boot: hdr.readBigUInt64LE(OFF_BOOT),
