  const plain = decryptAesCtr(K_enc, iv12, ct);
  let obj;
  try { obj = JSON.parse(plain.toString("utf8")); }
  catch { throw Error("plaintext is not valid JSON"); }

  msg.payload = obj;
  msg.secure = { deviceId, type, boot: boot.toString(), seq: seq.toString() };
  return msg;

} catch (e) {
  node.status({ fill: "red", shape: "ring", text: e.message });
  node.warn(`[SEC] drop: ${e.message}`);
  return null;
}

// Function: Chunk Sender
// Triggered by "need_chunks" event from ESP32
// Input: msg.payload = { next_offset, total }

const firmwareBuffer = flow.get('firmwareBuffer');
const chunkSize = flow.get('chunkSize') || 4096;
const totalSize = flow.get('firmwareSize');

if (!firmwareBuffer) {
    node.error("No firmware buffer found");
    return null;
}

// Parse incoming status
let status;
try {
    status = msg.payload;
} catch(e) {
    node.error("Invalid status JSON");
    return null;
}

const nextOffset = parseInt(status.next_offset) || 0;

// Check if complete
if (nextOffset >= totalSize) {
    node.status({fill:"green", shape:"dot", text:"Transfer complete"});

    // Send finish command
    msg.payload = JSON.stringify({ op: "finish" });
    msg.topic = "device/esp32-01/fota/cmd";
    return msg;
}

// Extract chunk
const end = Math.min(nextOffset + chunkSize, totalSize);
const chunk = firmwareBuffer.slice(nextOffset, end);
const chunkB64 = chunk.toString('base64');

// Build chunk message
const chunkMsg = {
    op: "chunk",
    offset: nextOffset,
    data_b64: chunkB64
};

msg.payload = JSON.stringify(chunkMsg);
msg.topic = "devices/esp32-01/fota/cmd";

// Update status
const progress = ((nextOffset / totalSize) * 100).toFixed(2);
node.status({fill:"yellow", shape:"ring", text:`Progress: ${progress}%`});

return msg;

// Function: FOTA Status Handler
// Processes status messages from ESP32
// Input: Decrypted msg.payload from ESP32

let status;
try {
    status = msg.payload;
} catch(e) {
    node.error("Invalid status JSON: " + msg.payload);
    return null;
}

const event = status.ev;

switch(event) {
    case "need_chunks":
        // ESP32 is ready for chunks
        node.status({fill:"blue", shape:"dot", text:"Sending chunks"});
        node.send([msg, null, null]); // Output 1: trigger chunk sender
        break;

    case "progress":
        // Update progress
        const pct = status.pct || 0;
        node.status({fill:"yellow", shape:"ring", text:`${pct.toFixed(1)}%`});

        // Continue sending chunks
        node.send([msg, null, null]); // Output 1: trigger chunk sender
        break;

    case "verify_ok":
        // SHA256 verified successfully
        node.status({fill:"green", shape:"dot", text:"Verified OK"});
        node.warn("Firmware verified: " + status.sha256_hex);

        // Send reboot command
        const rebootMsg = {
            topic: msg.topic.replace('/status', '/cmd'),
            payload: JSON.stringify({ op: "reboot" })
        };
        node.send([null, rebootMsg, null]); // Output 2: reboot
        break;

    case "verify_fail":
        // Verification failed
        node.status({fill:"red", shape:"dot", text:"Verify failed"});
        node.error("Verification failed: " + status.reason);
        node.send([null, null, status]); // Output 3: error
        break;

    case "rebooting":
        // ESP32 is rebooting
        node.status({fill:"blue", shape:"dot", text:"Rebooting..."});
        node.warn("Device rebooting into new firmware");
        break;

    case "error":
        // Error occurred
        node.status({fill:"red", shape:"dot", text:"Error"});
        node.error("FOTA Error: " + status.reason);
        node.send([null, null, status]); // Output 3: error
        break;

    default:
        node.warn("Unknown event: " + event);
}

return null;

